#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>
using namespace std;

int main() {
    int n, m, h, k;
    while (cin >> n >> m >> h >> k && n + m + h + k) {
        vector<int> a(n);
        for (int &x : a) cin >> x;

        vector<pair<int, int>> b(m);
        for (int i = 0; i < m; i++) {
            cin >> b[i].second >> b[i].first;  // Read q, p directly to avoid extra variables
        }

        sort(b.begin(), b.end());
        vector<int> c(n);
        iota(c.begin(), c.end(), 0);

        for (auto &pair : b) {
            swap(c[pair.second - 1], c[pair.second]);
            pair = {c[pair.second], c[pair.second - 1]}; // Use uniform initialization
        }

        vector<pair<int, int>> d(n);
        for (int i = 0; i < n; i++) d[i] = {c[i], a[i]}; // Use uniform initialization

        sort(d.begin(), d.end());
        int sm = accumulate(d.begin(), d.begin() + k, 0, [](int sum, pair<int, int> p) { return sum + p.second; });

        int mn = sm;
        for (auto &pair : b) {
            if (pair.first < k && pair.second >= k) {
                if (d[pair.first].second > d[pair.second].second)
                    mn = min(mn, sm - d[pair.first].second + d[pair.second].second);
            }
            if (pair.first >= k && pair.second < k) {
                if (d[pair.first].second < d[pair.second].second)
                    mn = min(mn, sm + d[pair.first].second - d[pair.second].second);
            }
        }
        cout << mn << endl;
    }
    return 0;
}

